36	export const DoorModel: FC<Props> = ({ proposal }) => {
37	  const isWholeModelShown = useIsWholeModelShown();
38	  const isFront = useIsFrontSide();
39	  const lightingMode = useSceneLightingMode();
40	  const setIsWholeModelShown = useSetIsWholeModelShown();
41	  const setIsFront = useSetIsFrontSide();
42	  const setLightingMode = useSetSceneLightingMode();
43	  const isNightMode = lightingMode.id === 'night';
44	
45	  useEffect(() => {
46	    if (!window) return;
47	    window.scrollTo({ top: 0, behavior: 'instant' });
48	  }, [isWholeModelShown]);
49	
50	  useEffect(() => {
51	    if (proposal?.sceneLightingMode) {
52	      setLightingMode(proposal.sceneLightingMode);
53	    }
54	  }, [proposal, setLightingMode]);
55	
56	  return (
57	    <div
58	      className={clsx(
59	        'sticky top-0 bg-background-7 md:relative h-[372px] md:h-full w-full z-10 md:z-0',
60	        isWholeModelShown ? 'col-[2_/_48]' : 'col-[1_/_49]  md:col-[2_/_29] ',
61	      )}
62	    >
63	      <div className="h-full md:h-screen w-full md:sticky md:top-0 md:pt-32">
64	        {!proposal && <DoorMobileNavigation />}
65	        {!proposal && <DoorNavigation />}
66	        <div
67	          className={clsx(
68	            'cursor-move relative mt-16',
69	            proposal
70	              ? 'h-[calc(100%-32px)]'
71	              : 'h-[calc(100%-100px)] md:h-[calc(100%-92px)]',
72	          )}
73	        >
74	          <Suspense
75	            fallback={
76	              <div className="absolute top-0 left-0 w-full h-full z-10 bg-black opacity-50 flex items-center justify-center transition-opacity duration-75 ease-out">
77	                <LoadingSpinner />
78	              </div>
79	            }
80	          >
81	            <Canvas
82	              dpr={[1, 2]}
83	              frameloop="demand"
84	              camera={{ position: [-4, 3, 6], fov: 45, near: 0.1, far: 200 }}
85	              shadows
86	              onCreated={({ gl }) => {
87	                gl.localClippingEnabled = true;
88	                gl.shadowMap.type = THREE.PCFSoftShadowMap;
89	              }}
90	            >
91	              <Door proposal={proposal} />
92	            </Canvas>
93	          </Suspense>
94	          <div className="absolute bottom-20 left-20 flex items-center gap-12">
95	            <button
96	              onClick={() => setIsFront(!isFront)}
97	              className="rounded-full bg-white w-44 h-44 flex justify-center items-center"
98	            >
99	              <Rotate />
100	            </button>
101	            <div className="flex items-center gap-10 rounded-full bg-white/95 h-44 px-14 shadow-[0_10px_28px_rgba(15,23,42,0.12)] backdrop-blur">
102	              <span
103	                className={clsx(
104	                  'text-xs font-medium transition-colors duration-300',
105	                  isNightMode ? 'text-text-3' : 'text-basic-black',
106	                )}
107	              >
108	                Day
109	              </span>
110	              <button
111	                onClick={() =>
112	                  setLightingMode({
113	                    ...lightingMode,
114	                    id: isNightMode ? 'day' : 'night',
115	                    name: isNightMode ? 'Day' : 'Night',
116	                  })
117	                }
118	                className={clsx(
119	                  'relative h-24 w-44 rounded-full transition-colors duration-300',
120	                  isNightMode ? 'bg-global-primary-1' : 'bg-border-5',
121	                )}
122	                aria-label="Toggle scene lighting"
123	                aria-pressed={isNightMode}
124	              >
125	                <span
126	                  className={clsx(
127	                    'absolute top-2 left-2 h-20 w-20 rounded-full bg-white transition-transform duration-300',
128	                    isNightMode && 'translate-x-[20px]',
129	                  )}
130	                />
131	              </button>
132	              <span
133	                className={clsx(
134	                  'text-xs font-medium transition-colors duration-300',
135	                  isNightMode ? 'text-basic-black' : 'text-text-3',
136	                )}
137	              >
138	                Night
139	              </span>
140	            </div>
141	          </div>
142	          <button
143	            onClick={() => setIsWholeModelShown(!isWholeModelShown)}
144	            className="hidden absolute bottom-20 right-20 rounded-full bg-white w-44 h-44 md:flex justify-center items-center"
145	          >
146	            {isWholeModelShown ? <Hide /> : <Show />}
147	          </button>
148	        </div>
149	      </div>
150	    </div>
151	  );
152	};
