33	interface DoorCameraControllerProps {
34	  controlsRef: React.RefObject<OrbitControlsImpl | null>;
35	  doorFocusY: number;
36	  isFront: boolean;
37	}
38	
39	const DoorCameraController: FC<DoorCameraControllerProps> = ({
40	  controlsRef,
41	  doorFocusY,
42	  isFront,
43	}) => {
44	  const { camera, invalidate } = useThree();
45	
46	  useEffect(() => {
47	    const controls = controlsRef.current;
48	
49	    if (!controls) return;
50	
51	    const interiorTargetZ = WALL_CENTER_Z - WALL_THICKNESS / 2 - 0.02;
52	    const target = new THREE.Vector3(
53	      0,
54	      doorFocusY,
55	      isFront ? 0 : interiorTargetZ,
56	    );
57	    const offset = isFront
58	      ? new THREE.Vector3(-1.4, 2.6, 5.8)
59	      : new THREE.Vector3(1.2, 1.5, -4.2);
60	
61	    controls.target.copy(target);
62	    camera.position.copy(target).add(offset);
63	    camera.lookAt(target);
64	    controls.update();
65	    invalidate();
66	  }, [camera, controlsRef, doorFocusY, invalidate, isFront]);
67	
68	  return null;
69	};
